const INTERNAL_NAMES = ["Atlas", "Open Design", "sub2api", "New API"];

const bare = await page.evaluate((terms) => {
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const out = [];
  let node;
  while ((node = walker.nextNode())) {
    if (node.parentElement.closest("[data-term]")) continue;
    for (const t of terms) {
      const re = new RegExp(`(^|[^A-Za-z])${t}([^A-Za-z]|$)`);
      if (re.test(node.textContent)) out.push({ term: t, 出现在: node.textContent.trim().slice(0, 60) });
    }
  }
  return out;
}, INTERNAL_NAMES);
must(bare.length === 0, `这些内部产品名裸着出现，后面没有说明：` + …);

